import Alpine from "alpinejs";

Alpine.data('main', () => ({
    destinations: null,
    init() {
        console.log('fetching')
        fetch('/api/destinations/all')
            .then((response) => response.json())
            .then((json) => this.destinations = json);
    },

    // footer
    status: '',
    mail: {
        name: '',
        email: '',
        message: '',
    },
    csrf() {
        let csrfElement = document.getElementById('token')?.firstElementChild as HTMLInputElement
        return csrfElement.value;
    },
    sendMail() {
        this.status = 'sending...'
        // Bundled TS isn't rendered by Django, so template tags can't be used here.
        fetch('/contact/sendmail/', {
            method: 'POST',
            headers: {
                Accept: 'application/json',
                'Content-Type': 'application/json',
                'X-CSRFToken': this.csrf(),
            },
            body: JSON.stringify(this.mail),
        }).then((response) => response.json())
            .then((json) => this.status = json);
        if (status === 'SUCCESS') {
            // clear fields
            this.mail.name = ''
            this.mail.email = ''
            this.mail.message = ''
        }
    }
}))